describe('Search Filter - No Results Message', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display "No results found" message when search returns no items', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform a search with a non-existent term
    cy.get('[data-testid="search-input"]').type('xyz123nonexistentterm');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.results).to.be.empty;
    });

    // Verify the "No results" message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

    // Verify the results list is empty
    cy.get('[data-testid="results-list"]').should('not.exist');

    // Verify the search input still contains the search term
    cy.get('[data-testid="search-input"]').should('have.value', 'xyz123nonexistentterm');

    // Verify the user can clear the search
    cy.get('[data-testid="clear-search-button"]').should('be.visible');
    cy.get('[data-testid="clear-search-button"]').click();
    cy.get('[data-testid="search-input"]').should('have.value', '');
  });

  it('should hide "No results" message when search returns results', () => {
    // Intercept the search API call with mock data
    cy.intercept('GET', '/api/search*', {
      statusCode: 200,
      body: {
        results: [
          { id: 1, name: 'Product A', category: 'electronics' },
          { id: 2, name: 'Product B', category: 'books' },
        ],
        total: 2,
      },
    }).as('searchRequestWithResults');

    // Perform a search with an existing term
    cy.get('[data-testid="search-input"]').type('product');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@searchRequestWithResults');

    // Verify the "No results" message is hidden
    cy.get('[data-testid="no-results-message"]').should('not.exist');

    // Verify results are displayed
    cy.get('[data-testid="results-list"]').should('be.visible');
    cy.get('[data-testid="results-item"]').should('have.length', 2);

    // Verify results contain the expected data
    cy.get('[data-testid="results-item"]').first().should('contain', 'Product A');
    cy.get('[data-testid="results-item"]').last().should('contain', 'Product B');

    // Verify the search input still contains the search term
    cy.get('[data-testid="search-input"]').should('have.value', 'product');
  });
});
